func:
var state = msg.payload;
if (typeof state === 'string') {
    try { state = JSON.parse(state); } catch (err) { node.error('Anlagenzustand ist kein gueltiges JSON', msg); return null; }
}
if (!state || typeof state !== 'object' || Array.isArray(state)) {
    node.error('Anlagenzustand muss ein JSON-Objekt sein', msg);
    return null;
}

var features = {};
for (var slot = 1; slot <= 9; slot += 1) {
    var key = 'storage_slot_' + slot + '_occupied';
    var value = Number(state[key]);
    if (value !== 0 && value !== 1) {
        node.error('Storage-Feature fehlt oder ist nicht binaer: ' + key, msg);
        return null;
    }
    features[key] = value;
}

var sequence = Number(flow.get('storage_request_sequence') || 0) + 1;
flow.set('storage_request_sequence', sequence);
var requestId = 'plc-storage-' + Date.now() + '-' + sequence;
flow.set('storage_pending', { request_id: requestId, state: JSON.parse(JSON.stringify(state)) });

msg.payload = JSON.stringify({
    request_id: requestId,
    source_id: 'plc_live',
    features: features
});
msg.qos = 1;
msg.retain = false;
return msg;

var response = msg.payload;
if (typeof response === 'string') {
    try { response = JSON.parse(response); } catch (err) { node.error('Storage-Response ist kein gueltiges JSON', msg); return null; }
}

var pending = flow.get('storage_pending');
if (!pending || !response || response.request_id !== pending.request_id) return null;
if (response.error) { node.error('Storage-ANN: ' + response.error, msg); return null; }

var emptyStorage = Number(response.empty_storage);
if (emptyStorage % 1 !== 0 || emptyStorage < 0 || emptyStorage > 9) {
    node.error('Ungueltiges Storage-Ergebnis: ' + response.empty_storage, msg);
    return null;
}

var state = pending.state;
state.empty_storage = emptyStorage;
for (var slot = 0; slot <= 9; slot += 1) {
    state['empty_storage_' + slot] = slot === emptyStorage ? 1 : 0;
}

var featureCols = [
    "IX_VGR_RefSwitchVerticalAxis_I1",
    "IX_VGR_RefSwitchHorizontalAxis_I2",
    "IX_VGR_RefSwitchRotate_I3",
    "QX_VGR_M2_HorizontalAxisBackward_Q3",
    "QX_VGR_M2_HorizontalAxisForward_Q4",
    "QX_VGR_Compressor_Q7",
    "QX_VGR_ValveVacuum_Q8",
    "VGR_vertical_position",
    "VGR_horizontal_position",
    "VGR_rotate_position",
    "IX_HBW_RefSwitchHorizontalAxis_I1",
    "IX_HBW_LightBarrierInside_I2",
    "IX_HBW_LightBarrierOutside_I3",
    "IX_HBW_RefSwitchVerticalAxis_I4",
    "IX_HBW_SwitchCantileverFront_I5",
    "IX_HBW_SwitchCantileverBack_I6",
    "HBW_vertical_position",
    "HBW_horizontal_position",
    "IX_SSC_LightBarrierStorage_I3",
    "empty_storage_0",
    "empty_storage_1",
    "empty_storage_2",
    "empty_storage_3",
    "empty_storage_4",
    "empty_storage_5",
    "empty_storage_6",
    "empty_storage_7",
    "empty_storage_8",
    "empty_storage_9"
];
var idleState = {
    "IX_VGR_RefSwitchVerticalAxis_I1": 1,
    "IX_VGR_RefSwitchHorizontalAxis_I2": 1,
    "IX_VGR_RefSwitchRotate_I3": 1,
    "QX_VGR_M2_HorizontalAxisBackward_Q3": 0,
    "QX_VGR_M2_HorizontalAxisForward_Q4": 0,
    "QX_VGR_Compressor_Q7": 0,
    "QX_VGR_ValveVacuum_Q8": 0,
    "VGR_vertical_position": 0,
    "VGR_horizontal_position": 0,
    "VGR_rotate_position": 0,
    "IX_HBW_RefSwitchHorizontalAxis_I1": 1,
    "IX_HBW_LightBarrierInside_I2": 1,
    "IX_HBW_LightBarrierOutside_I3": 1,
    "IX_HBW_RefSwitchVerticalAxis_I4": 1,
    "IX_HBW_SwitchCantileverFront_I5": 0,
    "IX_HBW_SwitchCantileverBack_I6": 1,
    "HBW_vertical_position": 0,
    "HBW_horizontal_position": 0,
    "IX_SSC_LightBarrierStorage_I3": 1
};

function featureVector(source) {
    var vector = [];
    for (var index = 0; index < featureCols.length; index += 1) {
        var feature = featureCols[index];
        var value;
        if (feature.indexOf('empty_storage_') === 0) {
            value = feature === 'empty_storage_' + emptyStorage ? 1 : 0;
        } else {
            if (!Object.prototype.hasOwnProperty.call(source, feature)) {
                throw new Error('LSTM-Feature fehlt: ' + feature);
            }
            value = Number(source[feature]);
            if (!isFinite(value)) {
                throw new Error('LSTM-Feature ist nicht numerisch: ' + feature);
            }
        }
        vector.push(value);
    }
    return vector;
}

var windowRows = flow.get('lstm_window');
try {
    if (!Array.isArray(windowRows) || windowRows.length === 0) {
        windowRows = [];
        for (var seed = 0; seed < 9; seed += 1) {
            windowRows.push(featureVector(idleState));
        }
    }
    windowRows.push(featureVector(state));
    windowRows = windowRows.slice(-10);
} catch (err) {
    node.error(err.message, msg);
    return null;
}

if (windowRows.length !== 10 || windowRows[0].length !== 29) {
    node.error('Ungueltiges LSTM-Fenster: erwartet 10x29', msg);
    return null;
}

flow.set('lstm_window', windowRows);
flow.set('storage_pending', null);

var cycleId = pending.request_id;
var commonRequest = {
    cycle_id: cycleId,
    parent_request_id: cycleId,
    source_id: 'plc_live',
    sequence: windowRows
};

var stateMessage = {
    payload: JSON.stringify(state),
    qos: 2,
    retain: true
};
var vgrMessage = {
    payload: JSON.stringify(Object.assign({}, commonRequest, { request_id: cycleId + ':vgr' })),
    qos: 1,
    retain: false
};
var hbwMessage = {
    payload: JSON.stringify(Object.assign({}, commonRequest, { request_id: cycleId + ':hbw' })),
    qos: 1,
    retain: false
};
var mpoMessage = { payload: '', qos: 2, retain: false };
var sldMessage = { payload: '', qos: 2, retain: false };

node.status({ fill: 'green', shape: 'dot', text: 'Fenster 10x29, Fach ' + emptyStorage });
return [stateMessage, vgrMessage, hbwMessage, mpoMessage, sldMessage];
